sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({api, helpers}) {
// debugger;
	const items = api.state.idouriyuu_choice;
	const listItems = items.map(v => {
		return {
			"id": v.value,
			"label": v.isplayValue
		};
	});
	return listItems;
}
